export const MAX_BATCH_BYTES = 50 * 1024 * 1024;

/** Stable for the same bytes and authorised competition, including after a page refresh. */
export async function batchUploadIdempotencyKey(
  competitionId: string,
  file: File,
): Promise<string> {
  if (!globalThis.crypto?.subtle) {
    throw new BatchUploadInputError('This browser cannot securely identify the upload for retry.');
  }
  const digest = await globalThis.crypto.subtle.digest('SHA-256', await file.arrayBuffer());
  const checksum = Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, '0'),
  ).join('');
  return `batch-upload:${competitionId}:${checksum}`;
}

const mediaTypesByExtension = {
  csv: 'text/csv',
  json: 'application/json',
  ndjson: 'application/x-ndjson',
} as const;

async function batchPackageVersion(file: File, mediaType: string): Promise<string> {
  if (mediaType !== 'application/json') return BATCH_PACKAGE_VERSION;

  try {
    const payload = JSON.parse(
      new TextDecoder().decode(new Uint8Array(await file.arrayBuffer())),
    ) as unknown;

    if (!payload || typeof payload !== 'object') return BATCH_PACKAGE_VERSION;

    const candidate = (payload as { contractVersion?: unknown }).contractVersion;
    if (
      typeof candidate === 'string' &&
      (BATCH_PACKAGE_VERSIONS as readonly string[]).includes(candidate)
    ) {
      return candidate;
    }

    // Keep staging behaviour unchanged for malformed/unsupported packages.
    // The worker remains responsible for the detailed validation report.
    return BATCH_PACKAGE_VERSION;
  } catch {
    return BATCH_PACKAGE_VERSION;
  }
}

export class BatchUploadInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'BatchUploadInputError';
  }
}

function parse<T>(
  value: unknown,
  schema: { safeParse(value: unknown): { success: boolean; data?: T } },
): T {
  const parsed = schema.safeParse(value);
  if (!parsed.success || parsed.data === undefined) {
    throw new Error('The batch API returned an invalid response.');
  }
  return parsed.data;
}

export async function listBatches(
  client: AuthenticatedApiClient,
  cursor?: string,
  status?: string,
): Promise<BatchListResponse> {
  const parameters = new URLSearchParams();
  if (cursor) parameters.set('cursor', cursor);
  if (status) parameters.set('status', status);
  const query = parameters.size > 0 ? `?${parameters.toString()}` : '';
  return parse(await client.request<unknown>(`/batches${query}`), batchListResponseSchema);
}

