function createNextCursor<T>(
  hasMore: boolean,
  records: T[],
  toCursor: (record: T) => unknown,
): string | null {
  if (!hasMore || records.length === 0) {
    return null;
  }

  const finalRecord = records[records.length - 1]!;

  return createCursor(toCursor(finalRecord));
}

