function optionSearch(filters: URLSearchParams, name: string): string {
  const params = new URLSearchParams(filters);
  params.set('limit', '100');
  params.delete('cursor');
  if (name) {
    params.set('name', name);
  }
  return `?${params.toString()}`;
}

