export function DetailLayout({
  backLabel,
  backTo,
  breadcrumbs,
  children,
  eyebrow,
  sections,
  title,
}: DetailLayoutProps) {
  return (
    <article className="detail-page content-boundary">
      <Breadcrumbs
        items={
          breadcrumbs ?? [
